+        $stmt = $conn->prepare("UPDATE users SET status = 'active' WHERE id = ? AND status = 'pending'");
+        $stmt->bind_param("i", $user_id);
+        
+        if ($stmt->execute() && $stmt->affected_rows > 0) {
+            // THIRD: Send approval email
